import{_ as n,a0 as d,w as p,s as h,ao as o,I as l,x as e,a1 as a,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"Bash 環境變量的那些事 | LCTT x X-CMD","titleTemplate":false,"description":"Bash 環境變量的那些事 | LCTT (201812) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Bash 環境變量的那些事 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Bash 環境變量的那些事 | LCTT (201812) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201812/20181205 Bash Variables- Environmental and Otherwise","title":"Bash 環境變量的那些事","tag":"201812","desc":""},"relativePath":"201812/20181205 Bash Variables- Environmental and Otherwise.md","filePath":"[post].md"}'),r={name:"201812/20181205 Bash Variables- Environmental and Otherwise.md"};function g(b,s,c,k,u,f){const i=d("Link");return p(),h("div",null,[s[31]||(s[31]=o(`<h1 id="bash-環境變量的那些事" tabindex="-1">Bash 環境變量的那些事 <a class="header-anchor" href="#bash-環境變量的那些事" aria-label="Permalink to “Bash 環境變量的那些事”">​</a></h1><blockquote><p>初學者可以在此教程中瞭解環境變量。</p></blockquote><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/wynand-van-poortvliet-40467-unsplash.jpg?itok=tr6Eb4N0" alt=""></p><p>bash 變量，尤其是討厭的<em>環境變量</em>，已經是一個老生常談的話題了。我們也更應該對它有一個詳細的瞭解，讓它為我們所用。</p><p>下面就打開終端，開始吧。</p><h3 id="環境變量" tabindex="-1">環境變量 <a class="header-anchor" href="#環境變量" aria-label="Permalink to “環境變量”">​</a></h3><p><code>HOME</code> （LCTT 譯註：雙關語）除了是你脱下帽子愜意休息的地方，同時也是 Linux 中的一個變量，它是當前用户主目錄的路徑：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo $HOME</span></span></code></pre></div><p>以上這個命令會顯示當前用户的主目錄路徑，通常都在 <code>/home/&lt;your username&gt;</code> 下。</p><p>顧名思義，變量的值是可以根據上下文變化的。實際上，Linux 系統中每一個用户的 <code>HOME</code> 變量都是不一樣的，當然你也可以這樣自行更改 <code>HOME</code> 變量的值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>HOME=/home/&lt;your username&gt;/Documents</span></span></code></pre></div><p>以上這個命令將會把 <code>HOME</code> 變量設置為你的 <code>Documents</code> 目錄。</p><p>其中有三點需要留意：</p><ol><li><code>=</code> 符號和其兩側的內容之間不加空格。空格在 shell 中有專門的意義，不能隨意地在任何地方添加空格。</li><li>如果你需要對變量進行賦值，只需要使用變量名稱就可以了。但如果需要讀取或者使用變量的值，需要在變量前面加上一個 <code>$</code> 號。</li><li>更改 <code>HOME</code> 變量具有一定的風險。有很多程序是依賴於 <code>HOME</code> 變量的，更改 <code>HOME</code> 變量可能會導致一些不可預見的結果。例如，如果按照上面的方式更改了 <code>HOME</code> 變量，然後執行不帶有任何參數的 <code>cd</code> 命令，在通常情況下，會跳轉到用户的主目錄下，但在這個時候，會跳轉到 <code>HOME</code> 變量指定的目錄下。</li></ol><p>上面第 3 點中環境變量的更改並不是持久有效的，在終端關閉後重新打開終端，又或者是新建一個終端，執行 <code>echo $HOME</code> 命令輸出的仍然會是初始的值，而不是重新自定義的值。</p><p>在討論如何持久地更改一個環境變量之前，我們先來看一下另一個比較重要的環境變量。</p><h3 id="path-變量" tabindex="-1">PATH 變量 <a class="header-anchor" href="#path-變量" aria-label="Permalink to “PATH 變量”">​</a></h3><p>在 <code>PATH</code> 變量中存放了一系列目錄，而且是放置了可執行程序的目錄。正是由於 <code>PATH</code> 變量的存在，讓你不需要知道應用程序具體安裝到了什麼目錄，而 shell 卻可以正確地找到這些應用程序。</p><p>如果你查看 <code>PATH</code> 變量的值，大概會是以下這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo $PATH</span></span>
<span class="line"><span>/usr/local/sbin:/usr/local/bin:/usr/bin:/usr/sbin:/bin:/sbin</span></span></code></pre></div><p>每兩個目錄之間使用冒號 <code>:</code> 分隔。如果某個應用程序的所在目錄不在 <code>PATH</code> 變量中，那麼運行的時候就需要聲明應用程序的目錄讓 shell 能夠找到。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/home/&lt;user name&gt;/bin/my_program.sh</span></span></code></pre></div><p>例如以上命令就會執行當前用户 <code>bin/</code> 目錄下的 <code>my_program.sh</code> 文件。</p><p>有一個常見的問題：如果你不希望弄亂系統的 <code>bin/</code> 目錄，同時也不希望你自己的文件被其它人運行，還不想每次運行的時候都要輸入完整的路徑，那麼，你可以在你的主目錄中創建一個獨立的 <code>bin/</code> 目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir $HOME/bin</span></span></code></pre></div><p>然後將這個目錄添加到 <code>PATH</code> 變量中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PATH=$PATH:$HOME/bin</span></span></code></pre></div><p>然後 <code>/home/&lt;user name&gt;/bin/</code> 目錄就會出現在 <code>PATH</code> 變量中了。但正如之前所説，這個變更只會在當前的 shell 生效，當前的 shell 一旦關閉，環境變量的值就又恢復原狀了。</p><p>如果要讓變更對當前用户持續生效，就不能在 shell 中直接執行對應的變更，而是應該將這些變更操作寫在每次啓動 shell 時都會運行的文件當中。這個文件就是當前用户主目錄中的 <code>.bashrc</code> 文件。文件名前面的點號表明這是一個隱藏文件，執行普通的 <code>ls</code> 命令是不會將這個文件顯示出來的，但只要在 <code>ls</code> 命令中加入 <code>-a</code> 參數就可以看到這個文件了。</p>`,29)),l("p",null,[s[4]||(s[4]=e("你可以使用諸如 ",-1)),a(i,{href:"https://www.kde.org/applications/utilities/kate/"},{default:t(()=>[...s[0]||(s[0]=[e("kate",-1)])]),_:1}),s[5]||(s[5]=e("、",-1)),a(i,{href:"https://help.gnome.org/users/gedit/stable/"},{default:t(()=>[...s[1]||(s[1]=[e("gedit",-1)])]),_:1}),s[6]||(s[6]=e("、",-1)),a(i,{href:"https://www.nano-editor.org/"},{default:t(()=>[...s[2]||(s[2]=[e("nano",-1)])]),_:1}),s[7]||(s[7]=e(" 或者 ",-1)),a(i,{href:"https://www.vim.org/"},{default:t(()=>[...s[3]||(s[3]=[e("vim",-1)])]),_:1}),s[8]||(s[8]=e(" 這些文本編輯器來打開 ",-1)),s[9]||(s[9]=l("code",null,".bashrc",-1)),s[10]||(s[10]=e(" 文件（但不要用 LibreOffice Writer，它是一個文字處理軟件，跟前面幾個文字編輯器完全不同）。打開 ",-1)),s[11]||(s[11]=l("code",null,".bashrc",-1)),s[12]||(s[12]=e(" 文件之後，你會看見裏面放置了一些 shell 命令，是用於為當前用户設置環境的。",-1))]),s[32]||(s[32]=o('<p>在文件的末尾添加新行並輸入以下內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>export PATH=$PATH:$HOME/bin</span></span></code></pre></div><p>保存並關閉 <code>.bashrc</code> 文件，接下來你就會看到 <code>export</code> 語句的效果。執行以下的命令讓剛才的修改立即生效：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>source .bashrc</span></span></code></pre></div><p>剛才執行的 <code>source</code> 命令讓 <code>.bashrc</code> 文件在當前的 shell 立即生效，並且對於之後打開的 shell 都會有效。因此另一個等效的方法是退出並重新進入 shell，但這樣也太麻煩了。</p><p>現在，你的 shell 就能自動尋找到 <code>/home/&lt;user name&gt;/bin/</code> 下的程序了，執行這個目錄下的程序也不需要完整地寫出程序的路徑。</p><h3 id="自定義變量" tabindex="-1">自定義變量 <a class="header-anchor" href="#自定義變量" aria-label="Permalink to “自定義變量”">​</a></h3>',7)),l("p",null,[s[14]||(s[14]=e("當然，你也可以定義自己的變量。剛才我們看到的變量名稱都是全大寫的，實際上",-1)),a(i,{href:"https://bash.cyberciti.biz/guide/Rules_for_Naming_variable_name"},{default:t(()=>[...s[13]||(s[13]=[e("變量名稱的定義還是比較靈活的",-1)])]),_:1}),s[15]||(s[15]=e("。",-1))]),s[33]||(s[33]=o(`<p>定義新變量的過程非常直觀，直接對它賦值就可以了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>new_variable=&quot;Hello&quot;</span></span></code></pre></div><p>然後可以用以下的方式讀取到已定義變量的值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo $new_variable</span></span></code></pre></div><p>程序的正常工作離不開各種變量，例如要將某個選項設置為打開，又或者讓程序找到所需的代碼庫，都需要使用變量。在 bash 中運行程序的時候會生成一個子 shell，這個子 shell 和執行原程序的父 shell 並不是完全一樣的，只是繼承了父 shell 的部分內容，而且默認是不繼承父 shell 中的變量的。因為變量默認情況下是局部變量，出於安全原因，一個 shell 中的局部變量不會被另一個 shell 讀取到，即使是子 shell 也不可以。</p><p>下面舉一個例子。首先定義一個變量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>robots=&quot;R2D2 &amp; C3PO&quot;</span></span></code></pre></div><p>然後執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>bash</span></span></code></pre></div><p>現在是在 bash shell 中創建了一個子 shell。</p><p>執行這個命令看看還能不能讀取到剛才定義的變量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo $robots</span></span></code></pre></div><p>你會發現讀取不到。</p><p>還是在這個子 shell 中，為 <code>robots</code> 變量賦一個不同的值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>robots=&quot;These aren&#39;t the ones you are looking for&quot;</span></span></code></pre></div><p>再讀取一次：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo $robots</span></span>
<span class="line"><span>These aren&#39;t the ones you are looking for</span></span></code></pre></div><p>退出這個子 shell：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>exit</span></span></code></pre></div><p>然後再看一下現在 <code>robots</code> 變量的值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo $robots</span></span>
<span class="line"><span>R2D2 &amp; C3P0</span></span></code></pre></div><p>這一個特性可以有效避免配置過程中產生混亂，同時也會導致一個問題：如果程序中需要設置變量，但卻由於子 shell 的原因無法正常訪問到這個變量，該如何解決呢？這個時候就需要用到 <code>export</code> 了。</p><p>重複一次剛才的過程，但這一次不是通過 <code>robots=&quot;R2D2 &amp; C3PO&quot;</code> 方式來設置變量，而是使用 <code>export</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>export robots=&quot;R2D2 &amp; C3PO&quot;</span></span></code></pre></div><p>現在你會發現，在進入子 shell 之後，<code>robots</code> 變量的值仍然是最初賦予的值。</p><p>要注意的是，儘管子 shell 會繼承通過 <code>export</code> 導出的變量，但如果在子 shell 中對這個變量重新賦值，是不會影響到父 shell 中對應變量的。</p><p>如果要查看所有通過 <code>export</code> 導出的變量，可以執行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>export -p</span></span></code></pre></div><p>自定義的變量會顯示在這個列表的末尾。這個列表中還有一些常見的變量：例如 <code>USER</code> 的值是當前用户的用户名，<code>PWD</code> 的值是當前用户當前所在的目錄，而 <code>OLDPWD</code> 的值則是當前用户上一個訪問過的目錄。因此如果執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd -</span></span></code></pre></div><p>就會切換到上一個訪問過的目錄，那是因為 <code>cd</code> 命令讀取到了 <code>OLDPWD</code> 變量的值。</p><p>你也可以使用 <code>env</code> 命令查看所有環境變量。</p><p>如果要取消導出一個變量，可以加上 <code>-n</code> 參數：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>export -n robots</span></span></code></pre></div><h3 id="接下來" tabindex="-1">接下來 <a class="header-anchor" href="#接下來" aria-label="Permalink to “接下來”">​</a></h3><p>瞭解過環境變量的知識之後，你已經到達了可能對自己和他人造成危險的水平，接下來就需要了解如何通過使用別名來讓環境變得更安全、更友好以保護自己了。</p><hr>`,37)),l("p",null,[s[17]||(s[17]=e("via: ",-1)),a(i,{href:"https://www.linux.com/blog/learn/2018/12/bash-variables-environmental-and-otherwise"},{default:t(()=>[...s[16]||(s[16]=[e("https://www.linux.com/blog/learn/2018/12/bash-variables-environmental-and-otherwise",-1)])]),_:1})]),l("p",null,[s[22]||(s[22]=e("作者：",-1)),a(i,{href:"https://www.linux.com/users/bro66"},{default:t(()=>[...s[18]||(s[18]=[e("Paul Brown",-1)])]),_:1}),s[23]||(s[23]=e(" 選題：",-1)),a(i,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[19]||(s[19]=[e("lujun9972",-1)])]),_:1}),s[24]||(s[24]=e(" 譯者：",-1)),a(i,{href:"https://github.com/HankChow"},{default:t(()=>[...s[20]||(s[20]=[e("HankChow",-1)])]),_:1}),s[25]||(s[25]=e(" 校對：",-1)),a(i,{href:"https://github.com/wxy"},{default:t(()=>[...s[21]||(s[21]=[e("wxy",-1)])]),_:1})]),l("p",null,[s[28]||(s[28]=e("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[26]||(s[26]=[e("LCTT",-1)])]),_:1}),s[29]||(s[29]=e(" 原創編譯，",-1)),a(i,{href:"https://linux.cn/"},{default:t(()=>[...s[27]||(s[27]=[e("Linux中國",-1)])]),_:1}),s[30]||(s[30]=e(" 榮譽推出",-1))])])}const v=n(r,[["render",g]]);export{C as __pageData,v as default};
